scwin.setSimulate1 = function() {
    WebSquare.wUnit.getJq('#wq_uuid_3_scrollY_div').animate({
        scrollTop: 200
    }, 500);
}
scwin.setSimulate2 = function() {
    WebSquare.wUnit.getJq('#wq_uuid_3_scrollY_div').animate({
        scrollTop: 120
    }, 500);
}
scwin.unitTest = function() {
    //init
    WebSquare.wUnit.start();
    //Test step 1. IE11에서 샘플파일을 실행 후 가로스크롤을 우측 끝으로 이동 후 세로스크롤을 내려본다.
    //1. Execute the sample file in IE11, move the horizontal scroll to the right end, and then try vertical scroll.
    //Verify step 1. The "2000" value of Change Reason 2 is shown as colMerge.(Previously not colMerge)
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('wq_uuid_3_scrollX_right').scrollLeft = 200");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "scwin.setSimulate1()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "scwin.setSimulate2()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('wq_uuid_3_cell_0_1').innerText == '2000'", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('wq_uuid_3_cell_1_1').innerText == ''", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('wq_uuid_3_cell_2_1').innerText == ''", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('wq_uuid_3_cell_3_1').innerText == ''", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    scwin.init();
    //Function 
    //Created by: Thuyet.Pham
    //Created date: 03-Apr-2018
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
